@startuml

class HospitalHouseMD {
  + name : string
}

class Patient {
  + name : string
  + symptoms : string
}

class Doctor {
  + name : string
  + practitionerNumber : int
}

class HeadDoctor {
  + name : string
}

class Diagnosis {
  + description : string
  + date : date
}

class Treatment {
  + name : string
  + description : string
}

class TreatmentStage {
  + stageNumber : int
}

enum PriorityScore {
  High
  Low
}

class Illness {
  + name : string
  + priority : PriorityScore
}

class ConsentForm {
  + signature : string
  + dateSigned : date
}

class Nurse {
  + name : string
}

class TreatmentRecord {
  + startDate : date
  + endDate : date
}

HospitalHouseMD "1" o-- "1..*" Patient
Patient "1" -- "1..*" Doctor
Doctor "1" -- "1..*" Diagnosis
Diagnosis "1" -- "1" Illness
Illness "1" -- "1..*" Treatment
Diagnosis "1" -- "1..*" TreatmentRecord
Treatment "1" -- "1" TreatmentStage
Patient "1" -- "0..*" ConsentForm
ConsentForm "1" -- "1" TreatmentRecord
HeadDoctor "1" -- "0..*" Diagnosis : approves
Nurse "1" -- "0..*" TreatmentRecord : monitors
Doctor "1" -- "0..*" TreatmentRecord : manages
TreatmentRecord "1" -- "1" Treatment
TreatmentRecord "1" -- "1" Diagnosis

@enduml

